/** Registration and authorization behavior, isolated from WP, CRM, tags and the network. */
require __DIR__.'/analysis-fixture/bootstrap.php';
final class XI_Analysis_Query {
 static $calls=array(); static $throw=false;
 static function answer($method,$input){self::$calls[]=array($method,$input);if(self::$throw)throw new RuntimeException('SQL secret email=buyer@example.invalid token=PRIVATE-TOKEN');return array('method'=>$method,'input'=>$input);}
 static function list_campaigns($input){return self::answer(__FUNCTION__,$input);}
 static function query_inquiries($input){return self::answer(__FUNCTION__,$input);}
 static function get_inquiry($input){return self::answer(__FUNCTION__,$input);}
 static function summarize_inquiries($input){return self::answer(__FUNCTION__,$input);}
 static function get_delivery_status($input){return self::answer(__FUNCTION__,$input);}
}
require dirname(__DIR__).'/xiaoman-inquiry-center/mcp-readonly.php';
